mapper.select:
select max(attempt_no)
from ai_video_task_attempt
where task_id = #{taskId}

mapper.update:
update ai_video_task_attempt
set provider_task_id = #{providerTaskId}
where task_id = #{taskId}
  and status in ('SUBMITTED', 'RUNNING')
  and attempt_no = (
      select max(attempt_no) from (
          select attempt_no from ai_video_task_attempt
          where task_id = #{taskId} and status in ('SUBMITTED', 'RUNNING')
      ) active_attempts
  )
